const src = $json.body?.currentMessage ?? $json.event ?? $json.currentMessage ?? $json;
const clean = v => v === undefined || v === null ? null : String(v).trim();
const attachments = Array.isArray(src.attachments) ? src.attachments.map((a, index) => ({ filename: clean(a.filename ?? a.name), content_type: clean(a.content_type ?? a.contentType ?? a.mimeType), size: Number.isFinite(Number(a.size)) ? Number(a.size) : null, url: clean(a.url), s3_key: clean(a.s3_key ?? a.s3Key), uploaded_at: clean(a.uploaded_at ?? a.uploadedAt), source_index: index })) : [];
const sender = clean(src.sender ?? src.from ?? src.sender_number);
const recipient = clean(src.recipient ?? src.to ?? src.recipient_number);
const content = clean(src.content ?? src.input_message ?? src.message) ?? '';
const messageId = clean(src.message_id ?? src.messageId);
const claimedDealerId = clean(src.dealer_id ?? src.dealerId);
const errors = [];
if (!sender) errors.push('MISSING_SENDER');
if (!recipient) errors.push('MISSING_RECIPIENT');
if (!messageId) errors.push('MISSING_MESSAGE_ID');
if (!content && attachments.length === 0) errors.push('EMPTY_MESSAGE');
return [{ json: { schema_version: '8.0', channel: 'sms', event: { type: 'inbound_message', message_id: messageId, parent_message_id: clean(src.parent_message_id ?? src.parentMessageId), content, sender, recipient, received_at: clean(src.date ?? src.timestamp ?? src.received_at) ?? new Date().toISOString(), attachments, raw_dealer_id: claimedDealerId }, identity: { dealer_id: null, customer_id: null, lead_id: null, conversation_id: null, parent_message_id: null }, context: { resolution: { valid_input: errors.length === 0, errors, warnings: [], claimed_dealer_id: claimedDealerId } }, intelligence: {}, inventory: null, decision: {}, response: {} } }];

const envelope = structuredClone($node['Normalize Input'].json);
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length && r._id);
const claimed = envelope.context.resolution.claimed_dealer_id;
const exact = claimed ? rows.filter(r => String(r._id) === claimed || String(r.dealer_id ?? '') === claimed) : rows;
const candidates = exact.length ? exact : rows;
if (candidates.length === 1) {
  const dealer = candidates[0];
  envelope.identity.dealer_id = String(dealer._id ?? dealer.dealer_id);
  envelope.context.dealer = {
    id: envelope.identity.dealer_id,
    bot_name: dealer.dealer_account_information?.ai_bot_name ?? dealer.ai_bot_name ?? null,
    store_name: dealer.dealer_account_information?.dealership_name ?? dealer.name ?? null,
    store_phone: dealer.dealer_account_information?.sms_conversion_phone ?? envelope.event.recipient,
    store_address: dealer.dealer_account_information?.address ?? dealer.address ?? null,
    store_website: dealer.dealer_account_information?.website ?? dealer.website ?? null,
    manager_name: dealer.dealer_account_information?.manager_name ?? dealer.manager_name ?? null,
    store_hours: dealer.dealer_account_information?.store_hours ?? dealer.store_hours ?? null,
    trade_url: dealer.dealer_account_information?.trade_in_appraisal_url ?? dealer.trade_in_appraisal_url ?? null,
    finance_url: dealer.dealer_account_information?.credit_finance_application_url ?? dealer.credit_finance_application_url ?? null
  };
} else {
  envelope.context.resolution.errors.push(candidates.length ? 'AMBIGUOUS_DEALER_PHONE' : 'DEALER_NOT_FOUND');
}
envelope.context.resolution.dealer_match_count = candidates.length;
envelope.context.resolution.valid = envelope.context.resolution.valid_input && candidates.length === 1;
return [{ json: envelope }];

const envelope = structuredClone($node['Validate Dealer Resolution'].json);
const truthy = v => v === true || v === 1 || v === '1' || String(v).toLowerCase() === 'true';
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length && (r._id || r.message_id));
rows.sort((a,b) => new Date(b.timestamp ?? b.created_at ?? 0) - new Date(a.timestamp ?? a.created_at ?? 0));
const usable = rows.filter(r => !truthy(r.internal_use) && (r.use_replies_for_ai === undefined || r.use_replies_for_ai === null || truthy(r.use_replies_for_ai)));
const latest = usable[0] ?? rows[0] ?? null;
const linked = usable.find(r => r.lead_id) ?? rows.find(r => r.lead_id) ?? null;
envelope.identity.conversation_id = latest ? String(latest.parent_message_id ?? latest.message_id ?? latest._id) : envelope.event.message_id;
envelope.identity.parent_message_id = latest ? String(latest.parent_message_id ?? latest.message_id ?? latest._id) : envelope.event.message_id;
envelope.identity.lead_id = linked?.lead_id ? String(linked.lead_id) : null;
envelope.context.resolution.conversation_record_count = rows.length;
envelope.context.resolution.usable_conversation_record_count = usable.length;
envelope.context.resolution.create_lead = !envelope.identity.lead_id;
envelope.context.resolution.update_lead = !!envelope.identity.lead_id;
return [{ json: envelope }];

const envelope = structuredClone($node['Resolve Conversation'].json);
const leads = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length && r._id);
const lead = leads[0] ?? null;
if (lead) {
  envelope.identity.lead_id = String(lead._id);
  envelope.identity.customer_id = lead.customer_id ? String(lead.customer_id) : null;
  envelope.context.lead = { id: String(lead._id), customer_id: envelope.identity.customer_id, name: lead.name ?? lead.customer_name ?? null, email: lead.email ?? null, phone: lead.phone ?? lead.phone_number ?? envelope.event.sender, vin: lead.vin ?? lead.vehicle_vin ?? null, make: lead.make ?? lead.vehicle_make ?? null, model: lead.model ?? lead.vehicle_model ?? null, year: lead.year ?? lead.vehicle_year ?? null, status: lead.status ?? null };
  envelope.context.resolution.create_lead = false;
  envelope.context.resolution.update_lead = true;
}
envelope.context.resolution.lead_match_count = leads.length;
if (leads.length > 1) envelope.context.resolution.warnings.push('MULTIPLE_LEAD_MATCHES_LATEST_NOT_GUARANTEED');
return [{ json: envelope }];

const envelope = structuredClone($node['Assemble Lead Resolution'].json);
const customers = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length && r._id);
if (customers[0]) {
  const c = customers[0];
  const primaryEmail = Array.isArray(c.emails) ? (c.emails.find(x => x?.is_primary)?.value ?? c.emails[0]?.value ?? null) : null;
  const primaryPhone = Array.isArray(c.phones) ? (c.phones.find(x => x?.is_primary)?.value ?? c.phones[0]?.value ?? null) : null;
  envelope.identity.customer_id = String(c._id);
  envelope.context.customer = { id: String(c._id), name: c.name ?? ([c.first_name, c.last_name].filter(Boolean).join(' ') || null), email: c.email ?? primaryEmail, phone: c.phone ?? c.phone_number ?? primaryPhone };
}
envelope.context.resolution.customer_match_count = customers.length;
envelope.context.resolution.completed_at = new Date().toISOString();
return [{ json: envelope }];
